using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using OrcaFacil.Application.Abstractions; using OrcaFacil.Application.Documents; using OrcaFacil.Domain.Enums;
namespace OrcaFacil.Web.Pages.Documents; [Authorize] public class CreateReceiptModel:PageModel{private readonly ICurrentUserService _current; private readonly DocumentService _service; public CreateReceiptModel(ICurrentUserService current,DocumentService service){_current=current;_service=service;} [BindProperty] public DocumentForm Input{get;set;}=DocumentForm.Default(); public async Task<IActionResult> OnPostAsync(CancellationToken ct){var cmd=new CreateDocumentCommand(_current.UserId,DocumentType.Receipt,"",Input.ClientName,Input.ToItems(),Input.Discount,Input.Notes); var r=await _service.CreateReceiptAsync(cmd,ct); if(!r.Succeeded){ModelState.AddModelError("",r.Error??"Erro ao criar recibo.");return Page();} return RedirectToPage("/Documents/Details",new{id=r.Value});}}
